          {rates.map((r) => (
            <tr key={`${r.grade}-${r.from}`} data-testid={`rate-row-${r.grade}-${r.from || 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from || 'start'}</td>
              <td data-testid="rate-pct">{r.rate}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="rate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ grade, rate: pct.trim(), from: from.trim() });
          });
        }}
      >
        <select
          data-testid="rate-form-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            save.reset();
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>{g}</option>
          ))}
        </select>{' '}
        <input
          data-testid="rate-form-pct"
          value={pct}
          placeholder="Rate %"
          onChange={(e) => {
            setPct(e.target.value);
            save.reset();
          }}
        />{' '}
        <input
          data-testid="rate-form-from"
          value={from}
          placeholder="From (YYYY-MM-DD, blank: always)"
          onChange={(e) => {
            setFrom(e.target.value);
            save.reset();
          }}
        />{' '}
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
        {save.isError && <span data-testid="rate-form-error" role="alert"> Could not set the rate: it must be a percent of 0.00 or more with at most two decimals, from a valid date (YYYY-MM-DD) or none.</span>}
      </form>
    </>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade's rate: a percent shown with two decimals ("12.50"), in force from a date (YYYY-MM-DD;
 *  "" for from the beginning of time). */
export type Rate = { grade: string; rate: string; from: string };

export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'] as const;

/** The sheet's rates, by grade then from-date (from the beginning of time first). */
export function useRates(sheet: string): Rate[] {
  const { data } = useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The grade's rate in force on a date: the one with the latest from-date on or before it;
 *  undefined when none applies (or the date is not known yet). */
export function rateOn(rates: Rate[], grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade === grade && r.from <= date && (found === undefined || r.from >= found.from)) found = r;
  }
  return found?.rate;
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a form tell a conflict (409) from a refusal. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useRef } from 'react';

/** Guards a form's submit so a second submit made before the first has answered (a double click)
 *  is ignored: the store gets one record, not two. A ref, not mutation state, so it holds even
 *  for two clicks landing before the next render. */
export function useSubmitOnce(): (run: () => Promise<unknown>) => void {
  const busy = useRef(false);
  return (run) => {
    if (busy.current) return;
    busy.current = true;
    run()
      .catch(() => {
        // the mutation shows its own error
      })
      .finally(() => {
        busy.current = false;
      });
  };
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The rate store: percents per grade, each from a date (or from the beginning of time), kept per sheet. */
@Repository
public class Rates {

    private final JdbcTemplate jdbc;

    public Rates(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's rates, by grade then from-date (from the beginning of time first). */
    public List<RateResponse> list(String sheetId) {
        return jdbc.query("SELECT grade, rate, from_date FROM rate WHERE sheet_id = ? ORDER BY grade, from_date NULLS FIRST",
                (rs, i) -> {
                    Date from = rs.getDate("from_date");
                    return new RateResponse(rs.getString("grade"), rs.getBigDecimal("rate").setScale(2).toPlainString(),
                            from == null ? "" : from.toLocalDate().toString());
                },
                sheetId);
    }

    /** The rate for a grade on the sheet in force on a date: the one with the latest from-date on or
     *  before it; null when none applies. */
    public BigDecimal find(String sheetId, String grade, LocalDate date) {
        List<BigDecimal> found = jdbc.query("SELECT rate FROM rate WHERE sheet_id = ? AND grade = ?"
                + " AND (from_date IS NULL OR from_date <= ?) ORDER BY from_date DESC NULLS LAST LIMIT 1",
                (rs, i) -> rs.getBigDecimal("rate"), sheetId, grade, Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** The due on an amount at a rate (a percent), rounded half to even to cents; null when there is no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate) {
        return rate == null ? null : amount.multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }

    /** Set the grade's rate from a date (null: from the beginning of time), replacing one already there. */
    public void set(String sheetId, String grade, LocalDate from, BigDecimal rate) {
        Date fromDate = from == null ? null : Date.valueOf(from);
        if (fromDate == null) {
            jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NULL", sheetId, grade);
        } else {
            jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date = ?", sheetId, grade, fromDate);
        }
        jdbc.update("INSERT INTO rate (sheet_id, grade, rate, from_date) VALUES (?, ?, ?, ?)",
                sheetId, grade, rate, fromDate);
    }
}

